PAGES['help']['sections'].append({'title':'문맥 확장과 업데이트','paragraphs':['검색 결과의 앞뒤 문맥에서 문맥 더 보기를 누르면 최대 앞뒤 100개 대사까지 펼칠 수 있습니다. 물리적으로 인접한 줄에는 다른 분기의 대사가 섞일 수 있습니다.','새 배포가 감지되면 업데이트 알림이 나타납니다. 지금 업데이트는 입력 중인 검색 조건을 주소에 보존하고 새 버전을 엽니다. 나중에 다시 알림은 30분 뒤 다시 표시합니다.']})
PAGES['changelog']['sections'].insert(0,{'title':'2026-10-22 · 네 언어 검색과 간결한 화면','paragraphs':['한국어·중국어·일본어·영어 화면과 대사 검색, 공식 ID를 사용한 인물 이름 연결, 검색창에 붙는 자동완성, 문맥 확장과 검색 링크 공유를 추가했습니다.','도움말을 사용 설명서로 모으고 물음표 아이콘, 하단 중앙 푸터, Tally 피드백, 새 버전 알림을 적용했습니다.']})

PAGES['help']['sections'].append({'title':'검색 화면과 결과 화면','paragraphs':['첫 화면의 중앙 검색창에서 조건을 입력하면 결과 화면으로 이동합니다. 대사 검색으로 버튼이나 브라우저 뒤로 가기로 돌아가면 입력한 조건이 유지됩니다. 결과 주소를 새로고침하거나 공유하면 같은 조건으로 검색합니다.','기기의 모션 줄이기 설정을 사용하면 화면 전환과 반복 애니메이션을 최소화합니다.']})
PAGES['changelog']['sections'].insert(0,{'title':'2026-10-22 · 중앙 검색과 결과 페이지','paragraphs':['중앙 검색 화면과 결과 화면을 분리하고 검색 조건을 유지하는 돌아가기, 브라우저 뒤로·앞으로 이동을 지원합니다.','버튼·입력창·카드 디자인을 통일하고 검색 로딩, 자동완성, 호버와 화면 이동 애니메이션을 추가했습니다. 모션 줄이기 설정을 존중합니다.']})

PAGES['help']['sections'].append({'title':'간결한 결과와 상세 정보','paragraphs':['사용 방법은 상단 물음표로 열고 Esc나 닫기로 닫습니다. 대사와 문맥의 작은 물음표를 누르면 파일·행·분기·버전을 확인할 수 있습니다. 서로 다른 분기의 인접 대사를 같은 대화로 간주하지 마세요.','파일명은 원본 경로이며 작품·이벤트의 공식 제목이 아닙니다. 대사 속 표현은 결과와 문맥에서 강조되며, 원문은 그대로 유지됩니다.']})
PAGES['changelog']['sections'].insert(0,{'title':'2026-10-22 · 도움말 모달과 결과 상세','paragraphs':['사용 방법을 모달로 바꾸고 L10ndiff의 언어 전환과 도움말 버튼 디자인을 적용했습니다. 파일·행·분기는 대사별 정보 버튼에서 확인합니다. 스토리 파일 필터와 표현 강조를 추가했습니다.']})

PAGES['help']['sections'].insert(0,{'title':'단어만 검색하기','paragraphs':['인물 칸을 비워두고 단어나 문구만 입력하면 모든 발화자의 대사를 검색합니다. 예를 들어 켈시를 입력하면 대사 본문에 켈시가 들어 있는 결과를 찾습니다. 인물을 추가하면 범위를 좁힙니다. 띄어쓰기와 대소문자를 포함해 입력한 문자열 그대로 찾습니다.','인물 초상화는 공식 ID로 연결한 기본 이미지입니다. 이름이 여러 인물과 겹치거나 이미지가 없으면 기본 아이콘을 표시합니다.']})
PAGES['changelog']['sections'].insert(0,{'title':'2026-10-22 · 단어 검색과 인물 초상화','paragraphs':['인물 선택 없이 단어만으로 모든 발화자의 대사를 검색할 수 있습니다. 자동완성과 결과·문맥에 인물 초상화를 추가했습니다.','푸터의 모든 링크를 선택한 화면 언어로 표시합니다. L10ndiff의 NEXON Lv2 Gothic 글꼴과 더 둥근 컨트롤, 중앙 정렬을 적용했습니다.']})

PAGES["changelog"]["sections"].insert(0,{"title":"2026-10-22 · 결과 화면 간소화","paragraphs":["검색 링크 복사·대사 출처 복사 버튼과 스토리 파일 드롭다운을 제거했습니다. 출처 정보는 대사 옆 물음표에서 확인할 수 있습니다."]})

PAGES["changelog"]["sections"].insert(0,{"title":"2026-10-22 · 언어 검색과 키보드 탐색","paragraphs":["다른 언어로 인물 이름을 입력해도 현재 대사 언어의 이름을 자동완성합니다. 상단 언어 선택과 대사 언어를 연결했습니다. 검색 전후 로고 위치와 탭 제목을 고정했습니다.","Tab 이동 순서를 검색 흐름에 맞추고 대사 언어 메뉴를 둥근 민트 디자인으로 통일했습니다."]})

PAGES["changelog"]["sections"].insert(0,{"title":"2026-10-22 · 문맥 중심의 결과","paragraphs":["다른 언어의 같은 줄 위치 후보를 제거하고, 선택한 언어의 대사와 앞뒤 문맥에 집중하도록 정리했습니다."]})

PAGES['help']['sections'].append({'title':'두 인물 검색의 순서','paragraphs':['같은 분기에서 상대 인물의 발화가 가까운 결과를 먼저 표시합니다. 각 방향 최대 6개 텍스트 행·원본 60행 안에서 다른 화자나 분기 경계가 나오기 전까지 확인합니다. 인접 발화만으로 직접 대화나 제삼자 언급을 확정하지 않습니다. 이름이 생략된 대사는 이 순위로 새로 검색되지 않습니다.','같은 파일·분기의 가까운 일치는 한 카드에서 문맥을 공유합니다. 각 대사 옆 물음표에서 원본 위치를 확인할 수 있습니다. 자막·내레이션·선택지는 화자를 임의로 붙이지 않고 이름 없음으로 표시합니다.']})
PAGES['changelog']['sections'].insert(0,{'title':'2026-10-22 · 대화 탐색과 Arknights Index','paragraphs':['브랜드명을 Arknights Index로 통일했습니다. 가까운 상대 발화가 있는 결과를 우선하고 겹치는 문맥을 한 카드에서 확인할 수 있습니다.','자막·내레이션·선택지·스티커 텍스트를 검색에 포함하고, 검색 데이터 생성과 UI 배포를 분리했습니다.']})
